PROGRAM ST120_UTTAGSROBOT
VAR
    steg        : INT := 0;
    trigOppet   : R_TRIG;
    tmrUttag    : TON;
    xVerktygOppnat : BOOL := FALSE;
    xTempLag    : BOOL := FALSE;
    xTempHog    : BOOL := FALSE;
    xUttagFel   : BOOL := FALSE;
    xDriftsklar : BOOL := FALSE;
    xUte        : BOOL := FALSE;
END_VAR

(* ST120_MLD_OPEN ar "Mould open position", stift ZA7 fran formsprutmaskinen.
   Uttaget startar pa givarens STIGANDE FLANK. Pa nivan startar uttaget om sig
   sjalvt sa fort forra cykeln ar klar och verktyget annu star oppet, och en
   tid raknad fran cykelstart gar in i verktyget nar kylningen forlangs. *)
trigOppet(CLK := ST120_MLD_OPEN);
xVerktygOppnat := trigOppet.Q;

(* Arbetsfonstret ar 40 till 80 C. Under 40 C fastnar detaljen i verktyget och
   maskinen far inte stanga och spruta in; over 80 C ar detaljen for mjuk for
   sugkopparna och uttaget far inte startas forran den kylt av. *)
xTempLag := ST120_MLD_TEMP < 40.0;
xTempHog := ST120_MLD_TEMP > 80.0;

(* Tidsovervakning: uttaget far ta 4,5 s av cykelns 28,0 s. Kommer inte
   ST120_RB_BUSY tillbaka lag inom 6,0 s star roboten kvar nagonstans pa
   vagen, och da far verktyget aldrig fa stangningsklart. *)
tmrUttag(IN := ST120_RB_BUSY, PT := T#6s);
IF tmrUttag.Q THEN
    xUttagFel := TRUE;
END_IF;
IF NOT ST120_RB_BUSY AND NOT ST120_MLD_OPEN THEN
    xUttagFel := FALSE;
END_IF;

xDriftsklar := EMG_OK AND SYS_AUTO AND NOT xUttagFel;

IF NOT xDriftsklar THEN
    (* Roboten kan sta kvar inne i verktyget och lagesbilden ar forlorad.
       A3/C3 oppnas: enligt EUROMAP 67 far verktyget da varken oppnas eller
       stangas. Vakuumet halls - ett slappt grepp har tappar detaljen, i
       varsta fall ner i verktyget. *)
    ST120_RB_START := FALSE;
    ST120_RB_CLEAR := FALSE;
    ST120_MLD_CLOSE_OK := FALSE;
    steg := 0;
ELSE
    CASE steg OF
        0:
            ST120_RB_START := FALSE;
            IF xVerktygOppnat THEN
                steg := 1;
            END_IF;
        1:
            (* Verktyget star oppet med detaljen kvar i formhalvan. *)
            IF NOT xTempHog THEN
                ST120_VAC_ON := TRUE;
                steg := 2;
            END_IF;
        2:
            IF ST120_VAC_OK THEN
                ST120_RB_START := TRUE;
                steg := 3;
            END_IF;
        3:
            IF ST120_RB_BUSY THEN
                ST120_RB_START := FALSE;
                steg := 4;
            END_IF;
        4:
            (* Detaljen ligger an mot avlaggsbandet forst nar roboten stannat.
               Ett vakuum som slapps under rorelsen tappar detaljen fran hojd. *)
            IF NOT ST120_RB_BUSY THEN
                ST120_VAC_ON := FALSE;
                steg := 0;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;

    (* A3/C3 "Mould area free", stift A3/C3 fran roboten till maskinen: sluten
       NAR roboten ar utanfor verktygsomradet. Kontakten oppnas redan nar
       uttaget begars, alltsa INNAN roboten kommenderas in - oppnas den forst
       efter kommandot finns ett scan dar maskinen far stanga om armen. *)
    xUte := (steg = 0) AND NOT ST120_RB_BUSY;
    ST120_RB_CLEAR := xUte;

    (* A6 "Enable mould closure": ges forst nar omradet ar fritt OCH gripdonet
       ar tomt. En detalj kvar pa sugkopparna kan falla ner i verktyget. Ett
       kallt verktyg sparrar ocksa stangningen: detaljen fastnar i formen. *)
    ST120_MLD_CLOSE_OK := xUte AND NOT ST120_VAC_ON AND NOT ST120_VAC_OK
                          AND NOT xTempLag;
END_IF;
END_PROGRAM

